args<-commandArgs(TRUE);root<-args[1];full<-file.path(root,'full');out<-file.path(full,'Litter_Application_Final')
suppressPackageStartupMessages(library(dplyr))
raw<-read.csv(file.path(full,'validation_raw.csv'));stopifnot(nrow(raw)==3000L,identical(unique(raw$MI),'REG'))
repdata<-raw|>group_by(replicate,MI,version)|>summarise(joint_recovered=first(joint_recovered),rep_length=first(mean_interval_length),rep_alpha=first(mean_alpha),rep_missing=first(realized_missing_pct),.groups='drop')
stopifnot(nrow(repdata)==1000L)
summary<-repdata|>group_by(MI,version)|>summarise(successful_replicates=n(),joint_benchmark_recovery_pct=100*mean(joint_recovered),mean_interval_length=mean(rep_length),sd_interval_length=sd(rep_length),mean_realized_missing_pct=mean(rep_missing),mean_alpha=if(first(version)=='Shrinkage')mean(rep_alpha)else NA_real_,.groups='drop')
stopifnot(nrow(summary)==2L,all(summary$successful_replicates==500L),all(is.finite(summary$sd_interval_length)))
sh<-summary|>filter(version=='Shrinkage')|>select(MI,sh_recovery=joint_benchmark_recovery_pct,sh_length=mean_interval_length,sh_alpha=mean_alpha)
ns<-summary|>filter(version=='Non-shrinkage')|>select(MI,ns_recovery=joint_benchmark_recovery_pct,ns_length=mean_interval_length)
diff<-inner_join(sh,ns,by='MI')|>mutate(recovery_difference_pp=sh_recovery-ns_recovery,interval_length_difference=sh_length-ns_length,relative_length_change_pct=100*(sh_length-ns_length)/ns_length)
stopifnot(nrow(diff)==1L)
archive<-file.path(full,'as_generated_validation_exports');dir.create(archive,showWarnings=FALSE)
for(name in c('litter_VALIDATION_SUMMARY.csv','litter_VALIDATION_SHRINKAGE_MINUS_NONSHRINK.csv'))if(!file.exists(file.path(archive,name)))file.copy(file.path(out,name),file.path(archive,name))
write.csv(summary,file.path(out,'litter_VALIDATION_SUMMARY.csv'),row.names=FALSE);write.csv(diff,file.path(out,'litter_VALIDATION_SHRINKAGE_MINUS_NONSHRINK.csv'),row.names=FALSE)
writeLines(c('Validation summary export repaired from unchanged raw repetition-level results.','Original dplyr summary recycled a vector-valued ifelse into 500 rows per group; this caused a many-to-many comparison join. Its sd(mean_interval_length) also operated on the newly summarized scalar and returned NA.','Corrected export uses per-repetition aliases, a scalar version condition, two procedure summary rows and one direct comparison row.','No imputations, treatment estimates, confidence intervals, original statistical functions, seeds or repetition outputs were changed. As-generated exports and warnings are retained in as_generated_validation_exports and warnings.csv.'),file.path(full,'SUMMARY_EXPORT_REPAIR.txt'))
print(summary);print(diff)
